package net.kikin.nubecita.feature.mediaviewer.api

import androidx.navigation3.runtime.NavKey
import kotlinx.serialization.Serializable

/**
 * Navigation 3 destination key for the fullscreen image viewer.
 *
 * Both fields are primitives:
 * - `postUri` is a plain `String` matching the project's NavKey shape.
 * - `imageIndex` is the zero-based position into the post's images payload.
 * - `contextKey` defaults to [postUri] to match the shared element transition
 *   bounds key generated by post cards.
 */
@Serializable
data class MediaViewerRoute(
    val postUri: String,
    val imageIndex: Int,
    val contextKey: String = postUri,
) : NavKey
